record.field:
# Define keywords
keywords = ['công ty', 'cty', 'doanh nghiệp', 'tnhh', 'chi nhánh', 'dntn', 'corporation', 'inc.', 'ltd']

# If triggered from Menu (no active_ids), search ALL candidates
if not env.context.get('active_ids'):
    # Search for Individual contacts (is_company=False) that have no parent
    records = env['res.partner'].search([('is_company', '=', False), ('parent_id', '=', False)])

# Process records
count = 0
for record in records:
    if not record.is_company and record.name:
        name_lower = record.name.lower()
        if any(kw in name_lower for kw in keywords):
            record.write({'is_company': True})
            count += 1

# Notify user
if not env.context.get('active_ids'):
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Hoàn thành',
            'message': 'Đã chuyển đổi %s liên hệ thành Công ty.' % count,
            'type': 'success',
            'sticky': False,
            'next': {'type': 'ir.actions.act_window_close'},
        }
    }
